<script setup>
import { computed, onMounted, ref } from 'vue'
import { useCalibrationStore } from '../stores/calibration'
import { useAuthStore } from '../stores/auth'
import { useRequestsStore } from '../stores/requests'
import DashboardRegistryModal from '../components/DashboardRegistryModal.vue'
const registryMode = ref(null)
const store=useCalibrationStore(),auth=useAuthStore(),requests=useRequestsStore()
const role=computed(()=>auth.user?.role||'customer');const firstName=computed(()=>auth.user?.fullName?.trim().split(/\s+/)[0]||'пользователь')
const action=computed(()=>role.value==='customer'?{to:'/requests',label:'＋ Создать заявку'}:role.value==='engineer'?{to:'/requests',label:'▤ Открыть заявки'}:{to:'/engineers',label:'＋ Управлять инженерами'})
const statusLabel={active:'Действующая',due:'Скоро поверка',overdue:'Просрочена',planned:'Принята в работу',in_progress:'В поверке',completed:'Завершена'}
const upcoming = computed(() => {
  const today = new Date(); today.setHours(0, 0, 0, 0)
  const end = new Date(today); end.setDate(end.getDate() + 30)
  return store.calibrations.filter(x => x.status !== 'completed' && x.scheduledAt && new Date(x.scheduledAt + 'T00:00:00') >= today && new Date(x.scheduledAt + 'T00:00:00') <= end).sort((a,b) => a.scheduledAt.localeCompare(b.scheduledAt))
})
onMounted(()=>{store.loadRemote();if(role.value!=='customer')requests.load()})
</script>
<template><section class="page"><div class="section-heading"><div><h2>Добрый день, {{firstName}}!</h2><p v-if="role==='admin'">Контролируйте сроки поверки и показатели предприятия.</p><p v-else-if="role==='engineer'">Проверьте новые заявки и отметьте передачу оборудования в поверку.</p><p v-else>Создавайте заявки на поверку и отслеживайте их выполнение.</p></div><RouterLink :to="action.to" class="btn-primary">{{action.label}}</RouterLink></div><div v-if="store.loadError" class="insight" style="margin-bottom:20px">{{store.loadError}}</div><template v-if="role==='admin'"><div class="stats-grid"><div class="stat-card"><span class="stat-title">ВСЕГО ОБОРУДОВАНИЯ</span><div class="stat-value">{{store.stats.total}}</div><div class="stat-note">в реестре предприятия</div><span class="stat-icon blue">◫</span></div><div class="stat-card"><span class="stat-title">ДЕЙСТВУЮЩИЕ ПОВЕРКИ</span><div class="stat-value">{{store.stats.active}}</div><div class="stat-note">свидетельства актуальны</div><span class="stat-icon green">✓</span></div><div class="stat-card"><span class="stat-title">ТРЕБУЮТ ВНИМАНИЯ</span><div class="stat-value">{{store.stats.due}}</div><div class="stat-note">в течение 30 дней</div><span class="stat-icon orange">◷</span></div><div class="stat-card"><span class="stat-title">ПРОСРОЧЕНЫ</span><div class="stat-value">{{store.stats.overdue}}</div><div class="stat-note">нужно принять меры</div><span class="stat-icon red">!</span></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><h3>Состояние парка оборудования</h3><p class="panel-subtitle">Распределение по текущему статусу</p></div><button class="link dashboard-link" @click="registryMode = 'equipment'">Открыть реестр →</button></div><div v-for="item in [{label:'Действующие',value:store.stats.active,color:'#55c49e'},{label:'Скоро поверка',value:store.stats.due,color:'#f2b85d'},{label:'Просроченные',value:store.stats.overdue,color:'#ef7581'}]" :key="item.label" class="progress-row"><span>{{item.label}}</span><div class="progress"><span :style="{width:(store.stats.total?item.value/store.stats.total*100:0)+'%',background:item.color}"/></div><b>{{store.stats.total?Math.round(item.value/store.stats.total*100):0}}%</b></div></div><div class="panel"><div class="panel-head"><div><h3>Ближайшие поверки</h3><p class="panel-subtitle">Следующие 30 дней</p></div><button class="link dashboard-link" @click="registryMode = 'calibrations'">Все поверки →</button></div><div v-for="x in upcoming.slice(0,4)" :key="x.id" class="schedule-item"><span class="day">{{x.scheduledAt.slice(8)}}<small> {{new Date(x.scheduledAt).toLocaleString('ru-RU',{month:'short'}).replace('.','')}}</small></span><div><b>{{x.equipmentName}}</b><small>{{x.provider}}</small></div><span :class="['tag',x.status==='overdue'?'danger':x.status==='due'?'warning':'ok']">{{statusLabel[x.status]}}</span></div><div v-if="!upcoming.length" class="empty">На ближайшие 30 дней поверки не запланированы</div></div></div></template><div v-else class="dashboard-grid"><div class="panel"><h3>{{role==='engineer'?'Новые задачи':'Нужна поверка оборудования?'}}</h3><p class="panel-subtitle" style="margin-top:8px">{{role==='engineer'?'В вашем списке активных заявок: '+requests.active.length+'.':'Создайте заявку, укажите прибор и удобную дату. Инженер-лаборант примет её в работу.'}}</p><RouterLink to="/requests" class="btn-primary" style="display:inline-block;margin-top:18px">{{role==='engineer'?'Перейти к заявкам':'Создать заявку'}}</RouterLink></div><div class="panel"><h3>Статус заявок</h3><p class="panel-subtitle" style="margin-top:8px">Всего активных заявок: {{requests.active.length}}.</p><p class="insight" style="margin-top:16px">Все изменения статуса отображаются здесь автоматически после обработки инженером-лаборантом.</p></div></div><DashboardRegistryModal v-if="role === 'admin' && registryMode" :mode="registryMode" @close="registryMode = null"/></section></template>

<style scoped>
.dashboard-link{border:0;background:transparent;padding:0;cursor:pointer;font-family:inherit}.dashboard-link:hover{text-decoration:underline}
</style>
